import React, { useState } from 'react';
import type { PriceInfo } from '@cloud-materials/common';
import { CFeeCalculator, Button } from '@cloud-materials/common';

interface Price {
  instanceTotol: number;
  instanceOrigin: number;
  volumeTotol: number;
  volumeOrigin: number;
  bandTotal: number;
  bandOrigin: number;
  ipTotal: number;
  ipOrigin: number;
}

interface CusDataItemType {
  name: string;
  num?: string;
  duration?: string;
  discount?: string;
  total?: number | string;
  originTotal?: number | string;
}

export default () => {
  const [formValues, setFormValues] = useState({ name: 100, age: 500 });

  const getPrice = async (): Promise<Price> => {
    return new Promise(resolve => {
      setTimeout(() => {
        const price = {
          instanceTotol: 100,
          instanceOrigin: 150,
          volumeTotol: 100,
          volumeOrigin: 150,
          bandTotal: 4.8,
          bandOrigin: 6,
          ipTotal: 3.2,
          ipOrigin: 4,
        };
        resolve(price);
      }, 500);
    });
  };

  return (
    <div>
      <span>当名称更新的时候触发重新计算：</span>
      <Button onClick={() => setFormValues({ name: formValues.name + 1, age: formValues.age })}>
        名称{formValues.name}
      </Button>
      <br />
      <span>当年龄更新的时候不会触发重新计算：</span>
      <Button onClick={() => setFormValues({ name: formValues.name, age: formValues.age + 1 })}>
        名称{formValues.age}
      </Button>
      <CFeeCalculator
        formValues={formValues}
        deps={['name']}
        numConfig={{
          showNum: true,
          initialNum: 2,
          maxNum: 15,
          numUnit: '台',
        }}
        durationConfig={{
          showDuration: true,
          initialDuration: 1,
          durationOptions: [
            { label: '1个月', value: 1 },
            { label: '2个月', value: 2 },
          ],
        }}
        handleData={async req => {
          const price = await getPrice();
          const resp: PriceInfo<CusDataItemType>[] = [
            {
              precision: 2,
              discountPrecision: 1,
              total: (price.instanceTotol + price.volumeTotol) * req.durationConfig.duration * req.numConfig.num,
              originalTotal:
                (price.instanceOrigin + price.volumeOrigin) * req.durationConfig.duration * req.numConfig.num,
              detailList: [
                {
                  name: '服务器',
                  num: `${req.numConfig.num}个`,
                  duration: `${req.durationConfig.duration}个月`,
                  discount: '75折',
                  total: `${price.instanceTotol * req.durationConfig.duration * req.numConfig.num}`,
                  originTotal: `${price.instanceOrigin * req.durationConfig.duration * req.numConfig.num}`,
                },
                {
                  name: '云盘',
                  num: `${req.numConfig.num}个`,
                  duration: `${req.durationConfig.duration}个月`,
                  discount: '75折',
                  total: `${price.volumeTotol * req.durationConfig.duration * req.numConfig.num}`,
                  originTotal: `${price.volumeOrigin * req.durationConfig.duration * req.numConfig.num}`,
                },
              ],
              // 默认值为价格明细
              detailTitle: '价格明细（自定义）',
              detailDesc: '以下为参考价格，具体收费情况请以账单为准。(自定义)',
              columns: [
                {
                  title: '计费项',
                  dataIndex: 'name',
                },
                {
                  title: '数量',
                  dataIndex: 'num',
                },
                {
                  title: '时长',
                  dataIndex: 'duration',
                },
                {
                  title: '原价',
                  dataIndex: 'originTotal',
                },
                {
                  title: '折扣',
                  dataIndex: 'discount',
                },
                {
                  title: '折扣价格',
                  dataIndex: 'total',
                  render: (col: any) => (
                    <span>
                      <span
                        style={{
                          color: '#f0a50f',
                          fontWeight: 600,
                        }}
                      >
                        $
                      </span>
                      {col}
                    </span>
                  ),
                },
              ],
            },
            {
              // 自定义价格标题
              title: '公网流量费',
              total: (price.bandTotal + price.ipTotal) * req.durationConfig.duration * req.numConfig.num,
              originalTotal: (price.bandOrigin + price.ipOrigin) * req.durationConfig.duration * req.numConfig.num,
              unit: '时',
              popoverProps: {
                title: '支持透传Popover的标题',
              },
              detailList: [
                {
                  name: '带宽费用',
                  total: price.bandTotal * req.durationConfig.duration * req.numConfig.num,
                  originTotal: price.bandOrigin * req.durationConfig.duration * req.numConfig.num,
                },
                {
                  name: 'IP配置费用',
                  total: price.ipTotal * req.durationConfig.duration * req.numConfig.num,
                  originTotal: price.ipOrigin * req.durationConfig.duration * req.numConfig.num,
                },
              ],
              columns: [
                {
                  title: '计费项',
                  dataIndex: 'name',
                },
                {
                  title: '原价',
                  dataIndex: 'originTotal',
                  render: (col: any) => (
                    <span>
                      <span
                        style={{
                          color: '#f0a50f',
                          fontWeight: 600,
                        }}
                      >
                        $
                      </span>
                      {col}/时
                    </span>
                  ),
                },
                {
                  title: '折扣价格',
                  dataIndex: 'total',
                  render: (col: any) => (
                    <span>
                      <span
                        style={{
                          color: '#f0a50f',
                          fontWeight: 600,
                        }}
                      >
                        $
                      </span>
                      {col}/时
                    </span>
                  ),
                },
              ],
            },
          ];
          return resp;
        }}
        className="custom"
        // 支持配置防抖时间
        // debounceTime={3000}
        onChange={item => console.log('onChange被触发', item)}
        onPriceChange={item => console.log('onPriceChange被触发', item)}
      />
    </div>
  );
};

