import type { PriceInfo } from '../interface';
import { useDebounceFn } from 'ahooks';

export default () => {
  const [value, setValue] = useState<PriceInfo[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  // 防抖
  const timeoutHandle = useDebounceFn(
    (num, duration) => {
      setIsLoading(true);
      setTimeout(() => {
        setValue([
          {
            total: num * duration * 10 * 0.8,
            originalTotal: num * duration * 10,
            showPopover: false,
          },
        ]);
        setIsLoading(false);
      }, 1000);
    },
    { wait: 500 },
  );

  return (
    <CFeeCalculator
      formValues={{ name: 'mongodb' }}
      onChange={({ num, duration }) => {
        timeoutHandle.run(num, duration);
      }}
      loading={isLoading}
      priceInfo={value}
      numConfig={{
        showNum: true,
        initialNum: 1,
        numUnit: '台',
      }}
      durationConfig={{
        showDuration: true,
        initialDuration: 1,
        durationOptions: [
          {
            label: '1个月',
            value: 1,
          },
          {
            label: '2个月',
            value: 2,
          },
        ],
      }}
    />
  );
